begin;
create table public.feature_flags(flag_key text primary key check(flag_key~'^[a-z0-9_]{3,50}$'),enabled boolean not null default false,description text not null default '',updated_by uuid references public.profiles(id),updated_at timestamptz not null default now());
insert into public.feature_flags(flag_key,enabled,description) values('ai_missions',true,'Geração assistida de missões'),('certificate_corrections',true,'Correções controladas de certificado'),('presentation_mode',true,'Roteiro local para demonstração');
alter table public.feature_flags enable row level security;revoke all on public.feature_flags from anon,authenticated;
create function public.get_public_feature_flags() returns table(flag_key text,enabled boolean) language sql stable security definer set search_path='' as $$select f.flag_key,f.enabled from public.feature_flags f$$;
create function public.update_feature_flag(target_key text,next_enabled boolean) returns boolean language plpgsql security definer set search_path='' as $$begin if not public.is_global_admin()then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;update public.feature_flags set enabled=next_enabled,updated_by=auth.uid(),updated_at=now()where flag_key=target_key;return found;end$$;
create table public.operation_rate_limits(id bigint generated always as identity primary key,user_id uuid not null,operation text not null,occurred_at timestamptz not null default now());create index operation_rate_limit_lookup on public.operation_rate_limits(user_id,operation,occurred_at desc);alter table public.operation_rate_limits enable row level security;revoke all on public.operation_rate_limits from anon,authenticated;
create function public.enforce_operation_rate_limit() returns trigger language plpgsql security definer set search_path='' as $$declare operation_name text:=tg_table_name;allowed integer:=case operation_name when 'help_requests' then 10 when 'mission_quality_feedback' then 20 else 3 end;begin if(select count(*) from public.operation_rate_limits where user_id=auth.uid()and operation=operation_name and occurred_at>now()-interval '1 hour')>=allowed then raise exception 'RATE_LIMIT_EXCEEDED' using errcode='P0001';end if;insert into public.operation_rate_limits(user_id,operation)values(auth.uid(),operation_name);return new;end$$;
create trigger rate_limit_help before insert on public.help_requests for each row execute function public.enforce_operation_rate_limit();create trigger rate_limit_feedback before insert on public.mission_quality_feedback for each row execute function public.enforce_operation_rate_limit();create trigger rate_limit_corrections before insert on public.certificate_correction_requests for each row execute function public.enforce_operation_rate_limit();
create function public.get_admin_system_health()returns table(component text,status text,details text)language plpgsql stable security definer set search_path='' as $$begin if not public.is_global_admin()then raise exception 'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;return query values('database','ok','Migrações operacionais disponíveis'),('rls','ok','Acesso por papel ativo'),('certificates',case when exists(select 1 from public.certificate_settings)then'ok'else'error'end,'Configuração institucional'),('catalog',case when exists(select 1 from public.mission_versions version where version.status='published')then'ok'else'warning'end,'Conteúdo publicado');end$$;
create function public.get_admin_certificates_page(search_term text default null,selected_status text default'all',page_limit integer default 20,page_offset integer default 0)returns table(certificate_id uuid,participant_name text,class_name text,issued_at timestamptz,revoked_at timestamptz,total_count bigint)language plpgsql stable security definer set search_path='' as $$begin if not public.is_global_admin()then raise exception'ADMIN_ACCESS_REQUIRED' using errcode='42501';end if;if page_limit not between 1 and 50 or page_offset<0 or selected_status not in('all','valid','revoked')then raise exception'INVALID_PAGE' using errcode='22023';end if;return query select c.id,c.participant_name,c.class_name,c.issued_at,c.revoked_at,count(*)over() from public.participation_certificates c where(nullif(btrim(search_term),'')is null or c.participant_name ilike'%'||btrim(search_term)||'%')and(selected_status='all'or selected_status='valid'and c.revoked_at is null or selected_status='revoked'and c.revoked_at is not null)order by c.issued_at desc limit page_limit offset page_offset;end$$;
revoke all on function public.get_public_feature_flags(),public.update_feature_flag(text,boolean),public.get_admin_system_health(),public.get_admin_certificates_page(text,text,integer,integer),public.enforce_operation_rate_limit() from public;grant execute on function public.get_public_feature_flags() to anon,authenticated;grant execute on function public.update_feature_flag(text,boolean),public.get_admin_system_health(),public.get_admin_certificates_page(text,text,integer,integer) to authenticated;
commit;
